import React, { useState } from 'react';
import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmCountryLanguageMismatch } from './index';

const meta: Meta<typeof ZimmCountryLanguageMismatch> = {
  title: 'Layout/ZimmCountryLanguageMismatch',
  component: ZimmCountryLanguageMismatch,
};
export default meta;
type Story = StoryObj<typeof ZimmCountryLanguageMismatch>;

// Both stories below are purely visual — no `play` function. The callback-wiring and
// copy-branch-per-variant behaviour that a `play` would otherwise assert is already covered,
// more precisely (exact `target` echo-back, onDismiss firing on every close path), by this
// component's own index.test.tsx — see .claude/rules/testing.md's "do not duplicate coverage
// across layers" note.

// Named component, not an inline `render: () => { useState(...) }` — see zimmDrawer's own story
// for why a lowercase `render` can't call hooks directly.
const LocationExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmCountryLanguageMismatch
      variant="location"
      isOpen={isOpen}
      onDismiss={() => setIsOpen(false)}
      inCountry="in Germany"
      currentStore="Zimmermann Australia"
      targetStore="Zimmermann Germany"
      target="ZimmermannEUde"
      onRedirect={() => setIsOpen(false)}
    />
  );
};

export const Location: Story = {
  render: () => <LocationExample />,
};

const LanguageExample = () => {
  const [isOpen, setIsOpen] = useState(true);
  return (
    <ZimmCountryLanguageMismatch
      variant="language"
      isOpen={isOpen}
      onDismiss={() => setIsOpen(false)}
      inCountry="in France"
      inLanguage="in French"
      inCurrentLanguage="in English"
      target="fr"
      onSwitchLanguage={() => setIsOpen(false)}
    />
  );
};

export const Language: Story = {
  render: () => <LanguageExample />,
};

